"""Cross-currency refund journal.

Standard library only, no floats. All arithmetic is done on exact Fractions
and rounded with ROUND_HALF_EVEN (Fraction.__round__ with no digits argument
rounds half to even and returns an int).

Dealer-quote convention: a pair "BASE/QUOTE" gives the price of 1 BASE in
QUOTE units. We are the dealer's customer, so:
  * we SELL BASE at the dealer's bid and BUY BASE at the dealer's ask.
Capture: we sold the local currency for USD.
Refund:  we buy the local currency with USD.

  Pair LOCAL/USD (local is base):
      sell local -> bid: USD = local * bid
      buy  local -> ask: USD = local * ask
  Pair USD/LOCAL (USD is base, rate is local per USD):
      sell local = buy USD  -> ask: USD = local / ask
      buy  local = sell USD -> bid: USD = local / bid
"""

from decimal import Decimal, InvalidOperation
from fractions import Fraction

__all__ = ["post_refund"]

# ISO 4217 minor-unit exponents that differ from the default of 2.
_EXP_0 = frozenset(
    "BIF CLP DJF GNF ISK JPY KMF KRW PYG RWF UGX UYI VND VUV XAF XOF XPF".split()
)
_EXP_3 = frozenset("BHD IQD JOD KWD LYD OMR TND".split())
_EXP_4 = frozenset("CLF UYW".split())


def _exponent(currency: str) -> int:
    if currency in _EXP_0:
        return 0
    if currency in _EXP_3:
        return 3
    if currency in _EXP_4:
        return 4
    return 2


def _is_int(value) -> bool:
    return isinstance(value, int) and not isinstance(value, bool)


def _is_code(value) -> bool:
    return (
        isinstance(value, str)
        and len(value) == 3
        and value.isascii()
        and value.isalpha()
        and value.isupper()
    )


def _parse_rate(value, name: str) -> Fraction:
    if not isinstance(value, str):
        raise ValueError(f"{name} must be a decimal string")
    try:
        d = Decimal(value.strip())
    except InvalidOperation:
        raise ValueError(f"{name} is not a valid decimal string: {value!r}")
    if not d.is_finite() or d <= 0:
        raise ValueError(f"{name} must be a finite positive number")
    return Fraction(d)


def _parse_quote(quote, currency: str, label: str):
    """Return (local_is_base, bid, ask) after validating the quote."""
    if not isinstance(quote, dict):
        raise ValueError(f"{label} must be a dict")
    pair = quote.get("pair")
    if not isinstance(pair, str) or pair.count("/") != 1:
        raise ValueError(f"{label}.pair must look like 'BASE/QUOTE'")
    base, quoted = pair.split("/")
    if not (_is_code(base) and _is_code(quoted)):
        raise ValueError(f"{label}.pair has invalid currency codes: {pair!r}")
    if base == currency and quoted == "USD":
        local_is_base = True
    elif base == "USD" and quoted == currency:
        local_is_base = False
    else:
        raise ValueError(
            f"{label}.pair {pair!r} does not match USD and {currency}"
        )
    bid = _parse_rate(quote.get("bid"), f"{label}.bid")
    ask = _parse_rate(quote.get("ask"), f"{label}.ask")
    if bid > ask:
        raise ValueError(f"{label} is crossed (bid > ask)")
    return local_is_base, bid, ask


def _usd_cents(local_minor: int, exp: int, parsed, we_sell_local: bool) -> int:
    """Exact USD value in cents (rounded half-even) of local_minor."""
    local_is_base, bid, ask = parsed
    major = Fraction(local_minor, 10 ** exp)
    if local_is_base:
        rate = bid if we_sell_local else ask
        usd = major * rate
    else:
        rate = ask if we_sell_local else bid
        usd = major / rate
    return round(usd * 100)


def post_refund(
    payment: dict,
    prior_refunds_minor: list[int],
    refund_minor: int,
    quote: dict,
) -> list[dict]:
    # ---- validation -------------------------------------------------------
    if not _is_int(refund_minor) or refund_minor <= 0:
        raise ValueError("refund_minor must be a positive integer")
    if not isinstance(payment, dict):
        raise ValueError("payment must be a dict")

    currency = payment.get("currency")
    if not _is_code(currency) or currency == "USD":
        raise ValueError("payment.currency must be a non-USD ISO 4217 code")

    total = payment.get("amount_minor")
    if not _is_int(total) or total <= 0:
        raise ValueError("payment.amount_minor must be a positive integer")

    fee_bps = payment.get("fee_bps")
    if not _is_int(fee_bps) or not (0 <= fee_bps <= 10000):
        raise ValueError("payment.fee_bps must be an integer in 0..10000")

    if not isinstance(prior_refunds_minor, (list, tuple)):
        raise ValueError("prior_refunds_minor must be a list of integers")
    for r in prior_refunds_minor:
        if not _is_int(r) or r <= 0:
            raise ValueError("prior refunds must be positive integers")

    c0 = sum(prior_refunds_minor)
    c1 = c0 + refund_minor
    if c1 > total:
        raise ValueError("cumulative refunds exceed captured amount")

    capture_parsed = _parse_quote(payment.get("capture_quote"), currency, "capture_quote")
    today_parsed = _parse_quote(quote, currency, "quote")

    exp = _exponent(currency)

    # ---- calculation ------------------------------------------------------
    proceeds = _usd_cents(total, exp, capture_parsed, we_sell_local=True)  # P
    fee = round(Fraction(proceeds * fee_bps, 10000))                       # F
    net = proceeds - fee                                                   # N

    def clawback(c: int) -> int:
        return round(Fraction(net * c, total))

    def fee_returned(c: int) -> int:
        return round(Fraction(fee * c, total))

    d_m = clawback(c1) - clawback(c0)
    d_g = fee_returned(c1) - fee_returned(c0)
    cost = _usd_cents(refund_minor, exp, today_parsed, we_sell_local=False)  # K

    # USD lines must sum to zero: dM + dG - K + fx = 0
    fx = cost - d_m - d_g

    # ---- journal ----------------------------------------------------------
    lines = [
        ("merchant_payable", "USD", d_m),
        ("fee_revenue", "USD", d_g),
        ("cash", "USD", -cost),
        ("fx_gain_loss", "USD", fx),
        ("fx_position", currency, refund_minor),
        ("customer_refunds", currency, -refund_minor),
    ]
    return [
        {"account": a, "currency": c, "amount_minor": amt}
        for a, c, amt in lines
        if amt != 0
    ]
```
